#!/usr/bin/env bash
# Idempotent builds needed before the dev processes and the tests: generated types, ui build. No containers.
# Usage: npm run dev-setup
set -euo pipefail
cd "$(dirname "$0")/.."

[ -d api/config/type/.type ] || npm run build-types
# vue-tsc needs the ui/dts files generated by the ui build
[ -f ui/dist/index.html ] || NODE_CONFIG_DIR="$PWD/api/config/" npm -w ui run build
